    /** Move the claim to {@code next}; with {@code judged}, who may settle it and the proof rule have
     * already been judged (on the claim a part-settle split it from); a settle with {@code on} is as of
     * that date (see {@link #settle}). */
    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason,
            boolean judged, LocalDate on) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Action action = switch (next) {
            case OPEN -> Action.OPEN;
            case SETTLED -> Action.SETTLE;
            case VOID -> Action.VOID;
            default -> null;
        };
        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
        refuseClosed(sheetId, claim.getDueBy());
        if (!claim.getStatus().canBecome(next)
                || ((claim.getStatus() == ClaimStatus.PENDING || claim.getStatus() == ClaimStatus.REVIEW) && next != ClaimStatus.VOID)) {
            throw new ClaimStatusChangeException();
        }
        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
        if (reversing) refuseLateVoid(sheetId, user, claim);
        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
        if (next == ClaimStatus.SETTLED && !judged && claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        if (next == ClaimStatus.OPEN && person.isFlaggedOn(sheets.today(sheetId))
                && settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimNotStewardException();
        }
        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String number = claim.getNumber();
        if (next == ClaimStatus.OPEN && overReview(claim, person)) {
            next = ClaimStatus.REVIEW;
            claim.setOpenedBy(user);
        } else if (next == ClaimStatus.OPEN) {
            claim.setOpenedBy(user);
        }
        BigDecimal dueThen = null;
        if (next == ClaimStatus.SETTLED && on != null) {
            if (on.isAfter(sheets.today(sheetId))) throw new ClaimSettleDateException();
            SheetAsOf then = history.asOf(sheetId, on);
            Claim stood = then.claims().stream().filter(c -> c.getId().equals(claim.getId())).findFirst()
                    .orElseThrow(ClaimSettleDateException::new);
            Person personThen = then.person(person.getId()).orElseThrow(ClaimSettleDateException::new);
            dueThen = rollup.shownOf(stood, personThen, then);
        }
        if (next == ClaimStatus.SETTLED) {
            BigDecimal due = on == null ? rollup.shownOf(claim, person) : dueThen;
            if (!judged) refuseUnproved(claim, person, due);
            if (overLimit(sheetId, user, person, due)) next = ClaimStatus.PENDING;
            else {
                claim.setSettledDue(due);
                if (number == null) number = nextNumber(sheetId, claim.getDueBy());
            }
        }
        claim.setStatus(next);
        claim.setNumber(number);
        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
        claims.flush();
        log(user, person, claim);
        String event = switch (next) {
            case OPEN -> "CLAIM_OPENED";
            case REVIEW -> "CLAIM_REVIEW";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT, DELETED -> throw new IllegalStateException();
        };
        if (next == ClaimStatus.SETTLED) {
            List<String> extra = new ArrayList<>(List.of("due=" + dueText(claim.getSettledDue())));
            if (on != null) extra.add("on=" + on);
            record(event, user, person, claim, number, extra.toArray(String[]::new));
            notifyWatchers(user, person, claim);
        } else {
            List<String> extra = new ArrayList<>();
            if (reversing) extra.add("reversed=" + dueText(claim.getSettledDue()));
            if (reason != null) extra.add("reason=" + reason);
            record(event, user, person, claim, number, extra.toArray(String[]::new));
        }
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

